#[tokio::test]
async fn every_command_kind_reports_authorization_unavailable_under_the_loopback_profile() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let unique = unique_id("work-command-api");
    let tenant_id = format!("tenant-{unique}");
    let repository_id = format!("repository-{unique}");
    enroll_repository(&database_url, &tenant_id, &repository_id, &unique).await;
    let app = application(&database_url, &tenant_id).await;

    for (kind, body) in command_fixtures() {
        let uri = format!("/api/v1/repositories/{repository_id}/work/commands");
        let (status, json) = post_json(&app, &uri, body).await;
        assert_eq!(
            status,
            StatusCode::OK,
            "{kind} should be a well-formed request"
        );
        assert_eq!(
            json,
            json!({
                "status": "authorization_unavailable",
                "reason": AUTHORIZATION_UNAVAILABLE_REASON,
            }),
            "{kind} must not execute under the loopback developer profile"
        );
    }
}

#[tokio::test]
async fn confirm_also_reports_authorization_unavailable_before_any_command_lookup() {
    let Ok(database_url) = std::env::var("ACKPLANE_TEST_DATABASE_URL") else {
        println!("skipped: ACKPLANE_TEST_DATABASE_URL not set");
        return;
    };
    let unique = unique_id("work-command-api-confirm");
    let tenant_id = format!("tenant-{unique}");
    let repository_id = format!("repository-{unique}");
    enroll_repository(&database_url, &tenant_id, &repository_id, &unique).await;
    let app = application(&database_url, &tenant_id).await;

    // No command with this id was ever submitted -- the authorization check
    // must still fire first (ADR-0125 decision 2), never leaking whether a
    // command id exists before authorization is even possible.
    let uri = format!(
        "/api/v1/repositories/{repository_id}/work/commands/never-submitted-command/confirm"
    );
    let (status, json) = post_json(
        &app,
        &uri,
        json!({"kind": "assign", "target_node_id": "node-1", "target_session_id": "session-1"}),
    )
    .await;
    assert_eq!(status, StatusCode::OK);
    assert_eq!(
        json,
        json!({
            "status": "authorization_unavailable",
            "reason": AUTHORIZATION_UNAVAILABLE_REASON,
        })
    );
}

